S = "Hakeem Force Academy"
QS = [
(S, "Which word is closest in meaning to 'dormant'?", ["Inactive", "Energetic", "Dangerous", "Noisy"], 0, "Dormant means temporarily inactive or sleeping, as in a dormant volcano.", "The opposite of dormant is active.", 1),
(S, "Which word is closest in meaning to 'evacuate'?", ["Occupy", "Vacate", "Protect", "Collect"], 1, "To evacuate is to leave or empty a place, especially because of danger.", "Evacuate comes from the Latin word vacuare, meaning to empty.", 1),
(S, "Which word is closest in meaning to 'exquisite'?", ["Ordinary", "Cheap", "Delicately beautiful", "Heavy"], 2, "Exquisite describes something extremely beautiful and finely made.", "Its opposite could be crude or coarse.", 1),
(S, "Which word is closest in meaning to 'persistent'?", ["Tenacious", "Lazy", "Careless", "Temporary"], 0, "Persistent means continuing firmly despite difficulty, which is what tenacious means.", "Persistent is the antonym of giving up or wavering.", 1),
(S, "Which word is closest in meaning to 'savage'?", ["Gentle", "Civilised", "Wild", "Quiet"], 2, "Savage means fierce, wild and untamed.", "Savage comes from the Latin silvaticus, meaning of the woods.", 1),
(S, "Which word is closest in meaning to 'voyage'?", ["Cart", "Ship", "Craft", "Journey"], 3, "A voyage is a long journey, especially by sea or in space.", "A voyage is the trip itself, while a ship is the vessel used.", 1),
(S, "What is a zero vector also called?", ["Unit vector", "Null vector", "Position vector", "Free vector"], 1, "A vector with zero magnitude and no definite direction is called a null vector.", "Adding a null vector to any vector leaves it unchanged.", 1),
(S, "What is the abscissa of a point in the Cartesian plane?", ["Its x-coordinate", "Its y-coordinate", "Its distance from the origin", "Its slope"], 0, "In a point (x, y), the abscissa is the x-coordinate, the horizontal distance from the y-axis.", "The y-coordinate is called the ordinate.", 1),
(S, "Another name for the Manila Pact of 1954 is:", ["CENTO", "SEATO", "NATO", "ASEAN"], 1, "The Manila Pact created the South East Asia Treaty Organization (SEATO), signed in Manila in September 1954.", "SEATO was dissolved in 1977.", 2),
(S, "What is Atomic Day (the day of Pakistan's 1998 nuclear tests) called in Pakistan?", ["Youm-e-Takbeer", "Youm-e-Pakistan", "Youm-e-Difa", "Youm-e-Istehsal"], 0, "Pakistan tested nuclear devices in the Chagai hills in 1998, and the day is observed as Youm-e-Takbeer.", "It is observed on 28 May each year.", 1),
(S, "In statistics, what is the average of a set of numbers also called?", ["Median", "Mode", "Mean", "Range"], 2, "The average is the sum of the values divided by their count, which is the arithmetic mean.", "The median is the middle value and the mode is the most frequent value.", 1),
(S, "What is Bait ul Muqaddas?", ["Masjid al-Aqsa in Jerusalem", "Masjid al-Haram in Makkah", "Masjid-e-Nabawi in Madinah", "Quba Mosque"], 0, "Bait ul Muqaddas means the Holy House and refers to Jerusalem and its Masjid al-Aqsa.", "It was the first Qibla of Muslims before the change to the Kaaba.", 1),
(S, "What is Barzakh in Islamic belief?", ["The bridge over Hell", "The period between death and the Day of Judgement", "The Day of Judgement itself", "The gate of Paradise"], 1, "Barzakh is the barrier or intermediate state between a person's death and resurrection.", "Barzakh is mentioned in Surah Al-Mu'minun of the Quran.", 1),
(S, "Which event is commemorated on Kashmir Day (Youm-e-Yakjehti-e-Kashmir) in Pakistan?", ["Solidarity with the people of Kashmir", "Independence of Pakistan", "Passing of the Lahore Resolution", "Pakistan's nuclear tests"], 0, "Kashmir Day is observed to express support for the Kashmiri right to self-determination.", "It is observed on 5 February each year.", 1),
(S, "What is cot x . sec x equal to?", ["Sin x", "Cos x", "Tan x", "Cosec x"], 3, "cot x = cos x / sin x and sec x = 1 / cos x, so the product = 1 / sin x = cosec x.", "Cosec x is the reciprocal of sin x.", 1),
(S, "What is the number of Hazrat Abu Bakr (RA) among the Khulafa-e-Rashideen?", ["First", "Second", "Third", "Fourth"], 0, "Hazrat Abu Bakr Siddiq (RA) was the first Rightly Guided Caliph after the Prophet (PBUH).", "The order is Abu Bakr, Umar, Uthman, Ali (RA).", 1),
(S, "What was Hilful Fudul?", ["A battle fought by Quraysh", "A peace pact of Makkan tribes to protect the oppressed", "A treaty between Muslims and Jews of Madinah", "A treaty signed at Hudaybiyyah"], 1, "Hilful Fudul was a pact formed in Makkah to defend the wronged and help the weak, and the young Prophet (PBUH) took part in it.", "The Prophet (PBUH) later said he would still respond to such a pact in Islam.", 1),
(S, "In vector algebra, what is the value of j . j (dot product of the unit vector j with itself)?", ["0", "1", "k", "-1"], 1, "j . j = |j||j|cos 0 = 1 x 1 x 1 = 1.", "Dot products of different unit vectors such as i . j are 0.", 1),
(S, "By what title is Liaquat Ali Khan known?", ["Quaid-e-Azam", "Quaid-e-Millat", "Allama", "Mujahid-e-Millat"], 1, "Liaquat Ali Khan, Pakistan's first Prime Minister, is called Quaid-e-Millat (leader of the nation).", "Quaid-e-Azam is the title of Muhammad Ali Jinnah.", 1),
(S, "What is Pakistan Standard Time relative to UTC?", ["UTC+4", "UTC+5", "UTC+5:30", "UTC+6"], 1, "Pakistan Standard Time (PST) is five hours ahead of Coordinated Universal Time.", "India uses UTC+5:30.", 1),
(S, "Which is the largest natural freshwater lake of Pakistan?", ["Keenjhar Lake", "Saiful Muluk", "Manchar Lake", "Haleji Lake"], 2, "Manchar Lake in Sindh is the largest freshwater lake in Pakistan.", "Keenjhar Lake is another large lake in Sindh and supplies water to Karachi.", 1),
(S, "Among Muslim-majority countries, what is Pakistan's rank by population?", ["First", "Second", "Third", "Fourth"], 1, "Indonesia has the largest population among Muslim-majority countries and Pakistan is second.", "Bangladesh is usually ranked third.", 1),
(S, "What is ping pong also called?", ["Badminton", "Squash", "Table tennis", "Lawn tennis"], 2, "Ping pong is the popular name of table tennis.", "Table tennis became an Olympic sport in 1988.", 1),
(S, "Which is the most populous district of Punjab, Pakistan?", ["Faisalabad", "Lahore", "Rawalpindi", "Multan"], 1, "Lahore has the largest population of any district in Punjab (about 13 million in the 2023 census).", "Lahore is also the capital of Punjab.", 1),
(S, "What is a Ruku in the Holy Quran?", ["A section of verses marked in the text", "A complete chapter", "A prostration", "A recitation prayer"], 0, "A ruku in the Quran is a group of verses forming a section, marked with the letter ain in the margin.", "In prayer, ruku also means bowing, but in the Mushaf it means a section.", 1),
(S, "What does SAFTA stand for?", ["South Asian Free Trade Area", "South Asian Federal Trade Agreement", "Southern Asia Fair Tariff Alliance", "South Asian Financial Trade Authority"], 0, "SAFTA is the South Asian Free Trade Area agreement among SAARC members.", "It came into force on 1 January 2006.", 1),
(S, "What is Sahih Muslim?", ["A book of Hadith", "A commentary on the Quran", "A book of Islamic history", "A book of Fiqh"], 0, "Sahih Muslim is a collection of authentic Hadith compiled by Imam Muslim ibn al-Hajjaj.", "Together with Sahih Bukhari it forms the Sahihain.", 2),
(S, "Stainless steel is mainly an alloy of iron with which metal?", ["Chromium", "Copper", "Zinc", "Aluminium"], 0, "Stainless steel is iron alloyed with at least about 10.5 percent chromium, which resists rust.", "Nickel is often added as well.", 1),
]
